DEFINE PROCEDURE my_db.public.my_proc()
RETURNS VARCHAR
LANGUAGE SQL
AS
$$
BEGIN
    RETURN 'Success';
END;
$$;

DEFINE SECURE PROCEDURE "my_proc"(input_value VARCHAR)
RETURNS VARCHAR
LANGUAGE SQL
EXECUTE AS CALLER
AS
$$
BEGIN
    RETURN input_value;
END;
$$;

DEFINE PROCEDURE js_proc(value FLOAT)
RETURNS FLOAT
LANGUAGE JAVASCRIPT
AS $$ return VALUE; $$;
